\label{def:Ipq}
Let $K\in\mathcal{K}^n$, and let $p,q\geq0$ be integers.
We say that $K$ satisfies property $(I_{p,q})$ if for any two faces $F$ and $G$ of $K$ with $\dim F\leq p$ and $\dim G\leq q$, the face $F\vee G$ is proper.

\label{lem:2cases}
Let $K\in\mathcal{K}^n$ be a full-dimensional convex body. Let $F$ and $G$ be proper faces of $K$ satisfying the following properties: 
\begin{align}
\label{eq:subface_property_F}
       \text{if } F'\text{ is a proper face of }F,\text{ then }F'\vee G\text{ is a proper face of }K;\\
\label{eq:subface_property_G}
       \text{if } G'\text{ is a proper face of }G,\text{ then }F\vee G'\text{ is a proper face of }K.
    \end{align}
Then  one of the following holds:
\begin{enuma}
\item $F\vee G $ is proper;
\item $F$ and $G$ are affinely independent, $K\cap \operatorname{aff}(F,G)=\operatorname{conv}(F,G)$, and for any extreme point $y\in G$ one has
\begin{align}
\label{eq:convFy}
(F\vee y)\cap\operatorname{aff}(F,G)=\operatorname{conv}(F,y).    
\end{align}
\end{enuma}

\label{pro:reduction_higher_godbersen}
    Let $K\in\mathcal{K}^n$ be a full-dimensional convex body. Let $f,g \geq 1$ be integers such that $f+g \geq n+1$. Then there exist proper faces $F,G$ of $K$ such that 
    \[\dim F \leq f-1, \qquad \dim G \leq g-1, \qquad\text{and}\qquad F \vee G = K.\]

\label{def:higherIp}
Let $K\in\mathcal{K}^n$ and fix integers $p\geq1$ and $q_0,\dots,q_p\geq0$.
We say that $K$ satisfies property $(I_{q_0,\dots, q_p})$ if for any faces $F_0,\dots,F_p$ of $K$ with $\dim F_i\leq q_i$, $i=0,\dots,p$, the face $F_0\vee\cdots\vee F_p$ is proper.
